// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address admin;
    function setUp() public { c = new Owned(); admin = c.owner(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != admin);
        vm.prank(caller);
        try c.setOwner(newOwner) { /* succeeded */ } catch { /* reverted */ }
        assertTrue(c.owner() == admin, "non-admin must not change owner");
    }
}
